use std::path::{Path, PathBuf};
use std::sync::Arc;
use parking_lot::Mutex;
use rand::Rng;
use serde_json::Value;
use steel::rvals::SteelVal;
use steel::steel_vm::register_fn::RegisterFn;
use game_script::{json_to_steel_val, steel_val_to_json, ScriptApp, ScriptWatcher};

use crate::types::{PlayerInput, PlayerSnapshot};

/// Outbound message generated by Scheme engine hooks to be dispatched by the host.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum OutboundMessage {
    SendMessage {
        player_id: u64,
        channel: String,
        text: String,
    },
    Broadcast {
        channel: String,
        text: String,
    },
}

fn steel_to_string(v: &SteelVal) -> String {
    match v {
        SteelVal::StringV(s) => s.to_string(),
        SteelVal::SymbolV(s) => s.to_string(),
        other => other.to_string(),
    }
}

pub fn compute_json_diff(old_val: &Value, new_val: &Value) -> Value {
    let mut added = serde_json::Map::new();
    let mut removed = serde_json::Map::new();
    let mut changed = serde_json::Map::new();

    fn diff_recursive(
        prefix: &str,
        old: &Value,
        new: &Value,
        added: &mut serde_json::Map<String, Value>,
        removed: &mut serde_json::Map<String, Value>,
        changed: &mut serde_json::Map<String, Value>,
    ) {
        if old == new {
            return;
        }

        match (old, new) {
            (Value::Object(old_map), Value::Object(new_map)) => {
                for (k, v_old) in old_map {
                    let path = if prefix.is_empty() {
                        k.clone()
                    } else {
                        format!("{}.{}", prefix, k)
                    };
                    if let Some(v_new) = new_map.get(k) {
                        diff_recursive(&path, v_old, v_new, added, removed, changed);
                    } else {
                        removed.insert(path, v_old.clone());
                    }
                }
                for (k, v_new) in new_map {
                    if !old_map.contains_key(k) {
                        let path = if prefix.is_empty() {
                            k.clone()
                        } else {
                            format!("{}.{}", prefix, k)
                        };
                        added.insert(path, v_new.clone());
                    }
                }
            }
            (Value::Array(old_arr), Value::Array(new_arr)) => {
                let max_len = old_arr.len().max(new_arr.len());
                for idx in 0..max_len {
                    let path = if prefix.is_empty() {
                        idx.to_string()
                    } else {
                        format!("{}.{}", prefix, idx)
                    };
                    match (old_arr.get(idx), new_arr.get(idx)) {
                        (Some(o), Some(n)) => {
                            diff_recursive(&path, o, n, added, removed, changed);
                        }
                        (Some(o), None) => {
                            removed.insert(path, o.clone());
                        }
                        (None, Some(n)) => {
                            added.insert(path, n.clone());
                        }
                        (None, None) => {}
                    }
                }
            }
            _ => {
                let key = if prefix.is_empty() {
                    "root".to_string()
                } else {
                    prefix.to_string()
                };
                changed.insert(
                    key,
                    serde_json::json!({
                        "old": old,
                        "new": new
                    }),
                );
            }
        }
    }

    diff_recursive("", old_val, new_val, &mut added, &mut removed, &mut changed);

    serde_json::json!({
        "added": added,
        "removed": removed,
        "changed": changed
    })
}

fn sort_script_files(files: &mut [PathBuf]) {
    files.sort_by(|a, b| {
        let is_prelude_a = a.file_name().is_some_and(|f| f == "prelude.scm");
        let is_prelude_b = b.file_name().is_some_and(|f| f == "prelude.scm");
        match (is_prelude_a, is_prelude_b) {
            (true, false) => std::cmp::Ordering::Less,
            (false, true) => std::cmp::Ordering::Greater,
            _ => a.cmp(b),
        }
    });
}

/// Scheme logic runner integrating Steel VM, hot reloading, and state management.
pub struct SchemeLogic {
    app: ScriptApp,
    scripts_dir: PathBuf,
    watcher: Option<ScriptWatcher>,
    save_file: Option<PathBuf>,
    outbound_queue: Arc<Mutex<Vec<OutboundMessage>>>,
    extra_version: u64,
}

impl SchemeLogic {
    /// Create a new `SchemeLogic` instance, register host functions, and prepare script paths.
    pub fn new(
        scripts_dir: impl Into<PathBuf>,
        watch_scripts: bool,
        save_file: Option<PathBuf>,
    ) -> Result<Self, Box<dyn std::error::Error>> {
        let scripts_dir = scripts_dir.into();
        let mut app = ScriptApp::new();
        let outbound_queue = Arc::new(Mutex::new(Vec::new()));

        // Register host functions
        let q1 = Arc::clone(&outbound_queue);
        app.engine.register_fn(
            "engine:send-message",
            move |pid: isize, channel: SteelVal, text: SteelVal| {
                q1.lock().push(OutboundMessage::SendMessage {
                    player_id: pid as u64,
                    channel: steel_to_string(&channel),
                    text: steel_to_string(&text),
                });
            },
        );

        let q2 = Arc::clone(&outbound_queue);
        app.engine.register_fn(
            "engine:broadcast",
            move |channel: SteelVal, text: SteelVal| {
                q2.lock().push(OutboundMessage::Broadcast {
                    channel: steel_to_string(&channel),
                    text: steel_to_string(&text),
                });
            },
        );

        app.engine.register_fn(
            "engine:log",
            move |text: SteelVal| {
                tracing::info!(target: "scheme", "{}", steel_to_string(&text));
            },
        );

        app.engine.register_fn(
            "engine:random-int",
            move |lo: isize, hi: isize| -> isize {
                let (min, max) = if lo <= hi { (lo, hi) } else { (hi, lo) };
                rand::thread_rng().gen_range(min..=max)
            },
        );

        app.engine.register_fn(
            "engine:strip-ansi",
            move |text: SteelVal| -> String {
                crate::runtime::strip_ansi_codes(&steel_to_string(&text))
            },
        );

        // Register safe datum parser helper (uses Scheme Reader only, never evals)
        let _ = app.engine.run(
            r#"
            (define (__engine:parse-datum s)
              (with-handler
                (lambda (err) s)
                (let ((d (read (open-input-string s))))
                  (if (eof-object? d) s d))))
            "#
            .to_string(),
        );

        app.with_load_path(&scripts_dir);

        let watcher = if watch_scripts && scripts_dir.is_dir() {
            Some(ScriptWatcher::new(&scripts_dir))
        } else {
            None
        };

        Ok(Self {
            app,
            scripts_dir,
            watcher,
            save_file,
            outbound_queue,
            extra_version: 0,
        })
    }

    /// Load scripts (`prelude.scm`, `main.scm`), call `(engine:on-init)`, and restore save file if present.
    pub fn init(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        let prelude_path = self.scripts_dir.join("prelude.scm");
        if prelude_path.exists() {
            let code = std::fs::read_to_string(&prelude_path)?;
            self.app
                .engine
                .compile_and_run_raw_program_with_path(code, prelude_path)?;
        }

        let main_path = self.scripts_dir.join("main.scm");
        if main_path.exists() {
            let code = std::fs::read_to_string(&main_path)?;
            self.app
                .engine
                .compile_and_run_raw_program_with_path(code, main_path)?;
        }

        // Initialize default world state
        self.app.call_function("engine:on-init", vec![])?;

        // If a save file exists, load it on top
        if let Err(e) = self.load_state_from_file() {
            tracing::warn!(error = %e, "Could not load existing save file, starting fresh world");
        }

        Ok(())
    }

    /// Whether this logic instance has a configured save file path.
    pub fn has_save_file(&self) -> bool {
        self.save_file.is_some()
    }

    /// Returns the configured save file path if any.
    pub fn save_file(&self) -> Option<&Path> {
        self.save_file.as_deref()
    }

    /// Whether script hot reloading file watcher is enabled.
    pub fn watch_enabled(&self) -> bool {
        self.watcher.is_some()
    }

    /// Query current target FPS from Scheme (clamped 1..=60, default 60).
    pub fn query_target_fps(&mut self) -> u64 {
        match self.app.call_function("engine:target-fps", vec![]) {
            Ok(SteelVal::IntV(n)) => (n as u64).clamp(1, 60),
            Ok(SteelVal::NumV(f)) => (f as u64).clamp(1, 60),
            _ => 60,
        }
    }

    /// Advance game tick `(engine:on-tick dt tick-id)`.
    pub fn on_tick(&mut self, dt: f32, tick_id: u64) -> Result<(), String> {
        let args = vec![
            SteelVal::NumV(dt as f64),
            SteelVal::IntV(tick_id as isize),
        ];
        self.app
            .safe_call_function("engine:on-tick", args, 500)
            .map_err(|e| format!("engine:on-tick error: {}", e))?;
        Ok(())
    }

    /// Handle player join event `(engine:on-player-join pid token)`.
    pub fn on_player_join(&mut self, pid: u64, token: &str) -> Result<(), String> {
        let args = vec![
            SteelVal::IntV(pid as isize),
            SteelVal::StringV(token.to_string().into()),
        ];
        self.app
            .safe_call_function("engine:on-player-join", args, 500)
            .map_err(|e| format!("engine:on-player-join error: {}", e))?;
        Ok(())
    }

    /// Handle player disconnect (entering grace period) `(engine:on-player-disconnect pid)`.
    pub fn on_player_disconnect(&mut self, pid: u64) -> Result<(), String> {
        let args = vec![SteelVal::IntV(pid as isize)];
        self.app
            .safe_call_function("engine:on-player-disconnect", args, 500)
            .map_err(|e| format!("engine:on-player-disconnect error: {}", e))?;
        Ok(())
    }

    /// Handle player reconnect (resuming within grace period) `(engine:on-player-reconnect pid)`.
    pub fn on_player_reconnect(&mut self, pid: u64) -> Result<(), String> {
        let args = vec![SteelVal::IntV(pid as isize)];
        self.app
            .safe_call_function("engine:on-player-reconnect", args, 500)
            .map_err(|e| format!("engine:on-player-reconnect error: {}", e))?;
        Ok(())
    }

    /// Handle player leave event `(engine:on-player-leave pid)`.
    pub fn on_player_leave(&mut self, pid: u64) -> Result<(), String> {
        let args = vec![SteelVal::IntV(pid as isize)];
        self.app
            .safe_call_function("engine:on-player-leave", args, 500)
            .map_err(|e| format!("engine:on-player-leave error: {}", e))?;
        Ok(())
    }

    /// Handle player key input `(engine:on-input pid input)`.
    pub fn on_input(&mut self, pid: u64, input: &PlayerInput) -> Result<(), String> {
        let json = match input {
            PlayerInput::Key {
                code,
                shift,
                ctrl,
                alt,
            } => {
                let mut map = serde_json::Map::with_capacity(5);
                map.insert("type".to_string(), Value::String("key".to_string()));
                map.insert("code".to_string(), Value::String(code.clone()));
                map.insert("shift".to_string(), Value::Bool(*shift));
                map.insert("ctrl".to_string(), Value::Bool(*ctrl));
                map.insert("alt".to_string(), Value::Bool(*alt));
                Value::Object(map)
            }
            PlayerInput::Mouse { x, y, button } => {
                let mut map = serde_json::Map::with_capacity(4);
                map.insert("type".to_string(), Value::String("mouse".to_string()));
                map.insert("x".to_string(), Value::Number((*x).into()));
                map.insert("y".to_string(), Value::Number((*y).into()));
                map.insert("button".to_string(), Value::String(button.clone()));
                Value::Object(map)
            }
            _ => serde_json::to_value(input).map_err(|e| e.to_string())?,
        };
        let val = json_to_steel_val(&json);
        let args = vec![SteelVal::IntV(pid as isize), val];
        self.app
            .safe_call_function("engine:on-input", args, 500)
            .map_err(|e| format!("engine:on-input error: {}", e))?;
        Ok(())
    }

    /// Handle player UI interaction `(engine:on-ui-action pid action)`.
    pub fn on_ui_action(&mut self, pid: u64, action: &str, payload: &Value) -> Result<(), String> {
        let mut map = serde_json::Map::new();
        map.insert("type".to_string(), Value::String("ui".to_string()));
        map.insert("action".to_string(), Value::String(action.to_string()));
        if let Value::Object(obj) = payload {
            for (k, v) in obj {
                map.insert(k.clone(), v.clone());
            }
        }
        map.insert("payload".to_string(), payload.clone());
        let val = json_to_steel_val(&Value::Object(map));
        let args = vec![SteelVal::IntV(pid as isize), val];
        self.app
            .safe_call_function("engine:on-ui-action", args, 500)
            .map_err(|e| format!("engine:on-ui-action error: {}", e))?;
        Ok(())
    }

    /// Handle normal player command `(engine:on-command pid datum raw)`.
    pub fn on_command(&mut self, pid: u64, raw: &str) -> Result<(), String> {
        let raw_val = SteelVal::StringV(raw.to_string().into());
        let datum = self
            .app
            .safe_call_function("__engine:parse-datum", vec![raw_val.clone()], 100)
            .unwrap_or_else(|_| raw_val.clone());

        let args = vec![
            SteelVal::IntV(pid as isize),
            datum,
            raw_val,
        ];
        self.app
            .safe_call_function("engine:on-command", args, 500)
            .map_err(|e| format!("engine:on-command error: {}", e))?;
        Ok(())
    }

    /// Render composite snapshot for an online player `(engine:render-snapshot pid)`.
    pub fn render_snapshot(&mut self, pid: u64) -> Result<PlayerSnapshot, String> {
        let args = vec![SteelVal::IntV(pid as isize)];
        let val = self
            .app
            .safe_call_function("engine:render-snapshot", args, 500)
            .map_err(|e| format!("engine:render-snapshot error: {}", e))?;

        if let SteelVal::HashMapV(ref hm) = val {
            let k_cols = SteelVal::StringV("cols".into());
            let k_rows = SteelVal::StringV("rows".into());
            let k_screen = SteelVal::StringV("screen".into());
            let k_hud = SteelVal::StringV("hud".into());

            if let (
                Some(SteelVal::IntV(cols)),
                Some(SteelVal::IntV(rows)),
                Some(SteelVal::StringV(screen)),
                Some(hud_val),
            ) = (
                hm.get(&k_cols),
                hm.get(&k_rows),
                hm.get(&k_screen),
                hm.get(&k_hud),
            ) {
                let hud = steel_val_to_json(hud_val)
                    .map_err(|e| format!("steel_val_to_json error: {}", e))?;
                return Ok(PlayerSnapshot {
                    cols: *cols as u16,
                    rows: *rows as u16,
                    screen: screen.to_string(),
                    hud,
                });
            }
        }

        let json = steel_val_to_json(&val)
            .map_err(|e| format!("steel_val_to_json error: {}", e))?;
        let snapshot: PlayerSnapshot = serde_json::from_value(json)
            .map_err(|e| format!("Failed to parse PlayerSnapshot: {}", e))?;
        Ok(snapshot)
    }

    /// Query current visual version counter to short-circuit unchanged snapshot rendering.
    pub fn visual_version(&self) -> u64 {
        let base = match self.app.extract_value("*visual-version*") {
            Ok(SteelVal::IntV(v)) => v as u64,
            _ => 0,
        };
        base.wrapping_add(self.extra_version)
    }

    /// Evaluate expression in REPL style with watchdog timeout.
    pub fn eval_repl(&mut self, code: &str) -> Result<String, String> {
        self.extra_version = self.extra_version.wrapping_add(1);
        self.app
            .safe_eval(code, 1000)
            .map_err(|e| format!("REPL error: {}", e))
    }

    /// Export world state as JSON value via `(engine:export-state)`.
    pub fn export_state(&mut self) -> Result<Value, String> {
        let val = self
            .app
            .safe_call_function("engine:export-state", vec![], 1000)
            .map_err(|e| format!("engine:export-state error: {}", e))?;
        steel_val_to_json(&val).map_err(|e| format!("export_state json error: {}", e))
    }

    /// Import world state from JSON value via `(engine:import-state data)`.
    pub fn import_state(&mut self, data: &Value) -> Result<(), String> {
        self.extra_version = self.extra_version.wrapping_add(1);
        let val = json_to_steel_val(data);
        self.app
            .safe_call_function("engine:import-state", vec![val], 1000)
            .map_err(|e| format!("engine:import-state error: {}", e))?;
        Ok(())
    }

    /// Atomically save world state to disk using `.tmp` and rename.
    pub fn save_state_to_file(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        let save_path = match &self.save_file {
            Some(p) => p.clone(),
            None => return Ok(()),
        };

        let state = self
            .export_state()
            .map_err(std::io::Error::other)?;

        if let Some(parent) = save_path.parent() {
            if !parent.as_os_str().is_empty() {
                std::fs::create_dir_all(parent)?;
            }
        }

        let tmp_path = save_path.with_extension(format!(
            "{}.tmp",
            save_path
                .extension()
                .and_then(|s| s.to_str())
                .unwrap_or("json")
        ));

        let content = serde_json::to_string_pretty(&state)?;
        std::fs::write(&tmp_path, content)?;
        std::fs::rename(&tmp_path, &save_path)?;

        tracing::debug!(path = %save_path.display(), "Game state atomically saved");
        Ok(())
    }

    /// Load world state from save file on disk.
    pub fn load_state_from_file(&mut self) -> Result<bool, Box<dyn std::error::Error>> {
        let save_path = match &self.save_file {
            Some(p) => p.clone(),
            None => return Ok(false),
        };

        if !save_path.exists() {
            return Ok(false);
        }

        let content = std::fs::read_to_string(&save_path)?;
        let json: Value = serde_json::from_str(&content)?;
        self.import_state(&json)
            .map_err(std::io::Error::other)?;

        tracing::debug!(path = %save_path.display(), "Game state loaded from save file");
        Ok(true)
    }

    /// Force immediate reload of all root `.scm` scripts in `scripts_dir` while preserving `*world-state*`.
    /// Ignores `watch_scripts` setting and file modification timestamps.
    pub fn force_reload(&mut self) -> Result<(), String> {
        tracing::info!(
            scripts_dir = %self.scripts_dir.display(),
            "Forcing immediate reload of Scheme scripts..."
        );
        let state = self.export_state().ok();

        let entries = std::fs::read_dir(&self.scripts_dir)
            .map_err(|e| format!("Failed to read scripts directory: {}", e))?;
        let mut files: Vec<PathBuf> = entries
            .filter_map(|e| e.ok().map(|entry| entry.path()))
            .filter(|f| f.is_file() && f.extension().is_some_and(|ext| ext == "scm"))
            .collect();
        sort_script_files(&mut files);

        // Read all target files first before running any compilation
        let mut sources = Vec::with_capacity(files.len());
        for file in files {
            let code = std::fs::read_to_string(&file)
                .map_err(|e| format!("Failed to read {}: {}", file.display(), e))?;
            sources.push((file, code));
        }

        for (file, code) in sources {
            if let Err(e) = self
                .app
                .engine
                .compile_and_run_raw_program_with_path(code, file.clone())
            {
                tracing::warn!(
                    file = %file.display(),
                    error = %e,
                    "Failed to compile script during reload, restoring state"
                );
                if let Some(st) = state {
                    let _ = self.import_state(&st);
                }
                return Err(format!("Failed to compile {}: {}", file.display(), e));
            }
        }

        if let Some(st) = state {
            let _ = self.import_state(&st);
        }
        if let Some(ref mut watcher) = self.watcher {
            let _ = watcher.check_modified();
        }
        self.extra_version = self.extra_version.wrapping_add(1);

        tracing::info!("Scripts reloaded successfully with state preserved");
        Ok(())
    }

    /// Check if watched `.scm` script files have been modified and reload with state preservation.
    pub fn check_reload(&mut self) -> Result<bool, Box<dyn std::error::Error>> {
        let is_modified = if let Some(ref mut watcher) = self.watcher {
            tracing::trace!(
                scripts_dir = %self.scripts_dir.display(),
                "Checking scripts directory for modifications"
            );
            watcher.check_modified()
        } else {
            return Ok(false);
        };

        if is_modified {
            tracing::info!("Script changes detected, reloading scripts...");
            self.force_reload()
                .map_err(|e| Box::new(std::io::Error::other(e)))?;
            return Ok(true);
        }
        Ok(false)
    }

    /// Query dynamically registered MCP tools from Scheme via `(engine:mcp-tools)`.
    pub fn mcp_list_tools(&mut self) -> Result<Value, String> {
        let val = self
            .app
            .safe_call_function("engine:mcp-tools", vec![], 500)
            .map_err(|e| format!("engine:mcp-tools error: {}", e))?;
        steel_val_to_json(&val).map_err(|e| format!("mcp_list_tools json error: {}", e))
    }

    /// Evaluates a Scheme assertion expression with a watchdog timeout.
    ///
    /// If the expression evaluates to non-`#f` (or truthy), returns `Ok(value_json)`.
    /// If the expression evaluates to `#f`, returns `Err("Assertion returned false (#f)".to_string())`.
    /// If an exception or timeout occurs, returns `Err(error_details)`.
    pub fn eval_assertion(&mut self, code: &str, timeout_ms: u64) -> Result<Value, String> {
        self.extra_version = self.extra_version.wrapping_add(1);
        let wrapped_code = format!(
            r#"(let ((__res (begin {})))
                 (if (equal? __res #f)
                     "__ASSERTION_FAILED_FALSE__"
                     __res))"#,
            code
        );
        match self.app.safe_eval(&wrapped_code, timeout_ms.max(1)) {
            Ok(output_str) => {
                let trimmed = output_str.trim();
                let res_str = trimmed.strip_prefix("=> ").unwrap_or(trimmed);
                if res_str == "\"__ASSERTION_FAILED_FALSE__\"" {
                    Err("Assertion failed: expression evaluated to #f".to_string())
                } else if res_str == "#t" || res_str == "#true" {
                    Ok(Value::Bool(true))
                } else if let Ok(i) = res_str.parse::<i64>() {
                    Ok(Value::Number(i.into()))
                } else if let Ok(f) = res_str.parse::<f64>() {
                    if let Some(n) = serde_json::Number::from_f64(f) {
                        Ok(Value::Number(n))
                    } else {
                        Ok(Value::String(res_str.to_string()))
                    }
                } else if res_str.starts_with('"') && res_str.ends_with('"') && res_str.len() >= 2 {
                    let unescaped = &res_str[1..res_str.len() - 1];
                    Ok(Value::String(unescaped.to_string()))
                } else {
                    Ok(Value::String(res_str.to_string()))
                }
            }
            Err(e) => Err(format!("Assertion error: {}", e)),
        }
    }

    /// Invoke a Scheme MCP tool handler via `(engine:on-mcp-call name args)`.
    pub fn mcp_call_tool(&mut self, name: &str, args: &Value) -> Result<Value, String> {
        self.extra_version = self.extra_version.wrapping_add(1);
        let args_val = json_to_steel_val(args);
        let call_args = vec![SteelVal::StringV(name.to_string().into()), args_val];
        let val = self
            .app
            .safe_call_function("engine:on-mcp-call", call_args, 1000)
            .map_err(|e| format!("engine:on-mcp-call error: {}", e))?;
        steel_val_to_json(&val).map_err(|e| format!("mcp_call_tool json error: {}", e))
    }

    /// Drain all queued outbound messages emitted by host functions.
    pub fn drain_outbound_messages(&mut self) -> Vec<OutboundMessage> {
        let mut guard = self.outbound_queue.lock();
        std::mem::take(&mut *guard)
    }
}

impl Drop for SchemeLogic {
    fn drop(&mut self) {
        if self.save_file.is_some() {
            if let Err(e) = self.save_state_to_file() {
                eprintln!("Failed to save state on drop: {}", e);
            }
        }
    }
}
